import html, re, sys
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack = []; self.skip = 0
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag in ('script', 'style', 'svg', 'helmet'): self.skip += 1
        lab = a.get('data-n') or a.get('data-c') or ''
        if tag == 'dc-import': print(f"  [import {a.get('name')} {' '.join(f'{k}={v}' for k, v in a.items() if k not in ('name','style','hint-size','theme'))}]")
        if tag in ('input',) and a.get('placeholder'): print(f"  [{tag} placeholder] {a['placeholder']}")
        if a.get('aria-label'): print(f"  [aria-label] {a['aria-label']}")
        if tag not in ('br', 'img', 'input', 'path', 'circle', 'rect', 'line', 'polyline'): self.stack.append(lab)
    def handle_endtag(self, tag):
        if tag in ('script', 'style', 'svg', 'helmet'): self.skip = max(0, self.skip - 1)
        if tag not in ('br', 'img', 'input', 'path', 'circle', 'rect', 'line', 'polyline') and self.stack: self.stack.pop()
    def handle_data(self, d):
        if self.skip: return
        t = ' '.join(d.split())
        if t:
            lab = next((l for l in reversed(self.stack) if l), '')
            print(f"{('<' + lab + '> ') if lab else ''}{t}")
for f in sys.argv[1:]:
